import json
import csv

# Read the solution
with open('/app/output/solution.json', 'r') as f:
    solution = json.load(f)

print("=== Solution Validation ===\n")
print(f"Status: {solution['status']}")
print(f"Makespan: {solution['makespan']}\n")

# Check downtime violations
print("Downtime constraints:")
print("  Machine 1: [5, 20)")
print("  Machine 2: [12, 25)\n")

violations = []
for item in solution['schedule']:
    machine = item['machine']
    start = item['start']
    end = item['end']
    job = item['job']
    op = item['op']

    if machine == 1 and not (end <= 5 or start >= 20):
        violations.append(f"J{job}O{op}: M{machine} [{start},{end})")
    if machine == 2 and not (end <= 12 or start >= 25):
        violations.append(f"J{job}O{op}: M{machine} [{start},{end})")

if violations:
    print("Downtime violations found:")
    for v in violations:
        print(f"  {v}")
else:
    print("✓ No downtime violations")

# Check job precedence
print("\nJob precedence:")
job_ops = {}
for item in solution['schedule']:
    if item['job'] not in job_ops:
        job_ops[item['job']] = {}
    job_ops[item['job']][item['op']] = item

errors = []
for job in job_ops:
    ops = job_ops[job]
    max_op = max(ops.keys())
    for op in range(max_op):
        if op in ops and op + 1 in ops:
            if ops[op]['end'] > ops[op+1]['start']:
                errors.append(f"J{job}: Op{op} ends at {ops[op]['end']}, Op{op+1} starts at {ops[op+1]['start']}")

if errors:
    print("Precedence violations:")
    for e in errors:
        print(f"  {e}")
else:
    print("✓ All job operations respect precedence")

# Check machine conflicts
print("\nMachine conflicts:")
machine_ops = {}
for item in solution['schedule']:
    if item['machine'] not in machine_ops:
        machine_ops[item['machine']] = []
    machine_ops[item['machine']].append(item)

conflicts = []
for machine in machine_ops:
    ops = machine_ops[machine]
    for i in range(len(ops)):
        for j in range(i+1, len(ops)):
            op1 = ops[i]
            op2 = ops[j]
            if not (op1['end'] <= op2['start'] or op2['end'] <= op1['start']):
                conflicts.append(f"M{machine}: J{op1['job']}O{op1['op']} and J{op2['job']}O{op2['op']} overlap")

if conflicts:
    print("Conflicts found:")
    for c in conflicts:
        print(f"  {c}")
else:
    print("✓ No machine conflicts")

print(f"\n=== FEASIBLE: {len(violations) == 0 and len(errors) == 0 and len(conflicts) == 0} ===")
